// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 warpTime) public {
        vm.assume(warpTime > 0);
        vm.warp(warpTime);

        address caller = address(0xA11CE);
        vm.deal(caller, 10 ether);
        vm.prank(caller);
        (bool ok1,) = address(c).call{value: 10 ether}("");
        assertTrue(ok1);

        // second call in the SAME block: must revert in reference C
        vm.deal(caller, 10 ether);
        vm.prank(caller);
        (bool ok2,) = address(c).call{value: 10 ether}("");
        assertTrue(!ok2, "second same-block call must revert");
    }
}
